    "a": {"healthcheck": True, "depends_on": {"b": "service_started"}},
    "b": {"healthcheck": True, "depends_on": {"a": "service_started"}},
}
services_fragile = {
    "worker": {"healthcheck": False, "depends_on": {"cache": "service_healthy"}},
